void ScriptSession::bindRescueNatives(){
    bind("SetUnitRescuable","nothing",{"unit","player","boolean"},[this](auto& vm,auto a){auto& u=unit(a[0]);auto bit=std::uint16_t(1u<<playerId(a[1]));if(a[2].bits){u.rescueEnabled|=bit;u.rescueDisabled&=std::uint16_t(~bit);}else{u.rescueEnabled&=std::uint16_t(~bit);u.rescueDisabled|=bit;}u.rescueNearby.clear();return vm.nothing();});
    bind("SetUnitRescueRange","nothing",{"unit","real"},[this](auto& vm,auto a){auto range=number(jass::Real::fromBits(a[1].bits));if(!std::isfinite(range) || range<0 || range>1000000)throw std::runtime_error("Invalid rescue range");auto& u=unit(a[0]);u.rescueRange=range;u.rescueNearby.clear();return vm.nothing();});
    bind("GetRescuer","unit",{},[this](auto& vm,auto){if(contexts_.empty() || (contexts_.back().event!=19 && contexts_.back().event!=63))return vm.handle("unit",0);return vm.handle("unit",contexts_.back().rescuer);});
}
