float ScriptSession::ownershipMana(const SpellInfo& s,const UnitState& target) const {return s.kind==SpellKind::ControlMagic?std::max(s.controlBaseMana,(s.controlCurrentLife?number(target.life):number(target.maxLife))*s.secondary):s.mana;}
